  const ok=reports.every(r=>r.ok),failure=reports.filter(r=>!r.ok).map(r=>r.name).join(', ');status.innerHTML=`<strong>${snapshot.installed?'Installed relay':'Selected relay site'} · <span class="${ok?'ok':'bad'}">${ok?'Connection possible':'Connection unlikely'}</span></strong><br>${ok?'Both links meet the connection requirements.':`${failure}  link needs another look.`}${snapshot.installed?'':' This relay has not been placed yet.'}`;
