 camera.position.set(snapshot.target[0]-cx,2,snapshot.target[1]-cy);const targets=[{name:'Base',p:snapshot.base},...(stage===1?[{name:snapshot.installed?'Relay':'Selected site',p:snapshot.relay}]:snapshot.relays.map(r=>({name:`Relay ${r.id}`,p:r.p})))];const initial=targets[1]?.p||snapshot.base;let yaw=Math.atan2(initial[1]-snapshot.target[1],initial[0]-snapshot.target[0]),pitch=.03;
 const overview=document.querySelector('#overview'), points=[{name:'You',p:snapshot.target},...targets], xs=points.map(o=>o.p[0]),ys=points.map(o=>o.p[1]), minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),span=Math.max(maxX-minX,maxY-minY,500)*1.35,midX=(minX+maxX)/2,midY=(minY+maxY)/2;
